#define MAXN 305
#define EPS 1e-9

int n;
double cx[MAXN], cy[MAXN], cr[MAXN], cm[MAXN];
double bcx[MAXN*2], bcy[MAXN*2], bcr[MAXN*2];
int bn;

int check(double px, double py) {
    int cnt = 0;
    for (int i = 0; i < n; i++) {
        double d = sqrt((px-cx[i])*(px-cx[i]) + (py-cy[i])*(py-cy[i]));
        double inner = fabs(cr[i]) - cm[i]; if (inner < 0) inner = 0;
        double outer = cr[i] + cm[i];
        if (d >= inner - EPS && d <= outer + EPS) cnt++;
    }
    return cnt;
}

int main() {
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%lf %lf %lf %lf", &cx[i], &cy[i], &cr[i], &cm[i]);
        // two boundary circles
        bcx[bn] = cx[i]; bcy[bn] = cy[i]; bcr[bn] = cr[i]+cm[i]; bn++;
        double inner = cr[i] - cm[i];
        if (inner > 0) { bcx[bn]=cx[i]; bcy[bn]=cy[i]; bcr[bn]=inner; bn++; }
    }
    int ans = 1;
    // check center of each boundary circle
    for (int i = 0; i < bn; i++) {
        ans = fmax(ans, check(bcx[i]+bcr[i], bcy[i]));
        ans = fmax(ans, check(bcx[i]-bcr[i], bcy[i]));
    }
    for (int i = 0; i < bn; i++) {
        for (int j = i+1; j < bn; j++) {
            double dx = bcx[j]-bcx[i], dy = bcy[j]-bcy[i];
            double d = sqrt(dx*dx+dy*dy);
            if (d < EPS) continue;
            double r1=bcr[i], r2=bcr[j];
            if (d > r1+r2+EPS || d < fabs(r1-r2)-EPS) continue;
            double a = (r1*r1 - r2*r2 + d*d)/(2*d);
            double h2 = r1*r1 - a*a;
            if (h2 < 0) h2 = 0;
            double h = sqrt(h2);
            double mx = bcx[i] + a*dx/d, my = bcy[i] + a*dy/d;
            double px1 = mx + h*dy/d, py1 = my - h*dx/d;
            double px2 = mx - h*dy/d, py2 = my + h*dx/d;
            ans = fmax(ans, check(px1,py1));
            ans = fmax(ans, check(px2,py2));
        }
    }
    printf("%d\n", ans);
}

