typedef struct {
    double x, y, r, m;
} Circle;

static const double EPS = 1e-9;

static int cmp_double(double a, double b) {
    if (a < b - EPS) return -1;
    if (a > b + EPS) return 1;
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Circle *c = (Circle *)malloc(sizeof(Circle) * n);
    for (int i = 0; i < n; i++) {
        scanf("%lf %lf %lf %lf", &c[i].x, &c[i].y, &c[i].r, &c[i].m);
    }

    int ans = 0;

    /* Check all circle centers as candidate rod positions */
    for (int i = 0; i < n; i++) {
        int cnt = 0;
        for (int j = 0; j < n; j++) {
            double dx = c[i].x - c[j].x;
            double dy = c[i].y - c[j].y;
            double d = sqrt(dx * dx + dy * dy);
            if (d <= c[j].r + c[j].m + EPS && d + EPS >= c[j].r) cnt++;
        }
        if (cnt > ans) ans = cnt;
    }

    /* Check all pairwise intersection points of attraction annulus boundaries:
       distance to center = r + m and distance to center = r
       Maximum of covered regions occurs at arrangement vertices, so these suffice
       together with centers above.
    */
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            double radii_i[2] = { c[i].r, c[i].r + c[i].m };
            double radii_j[2] = { c[j].r, c[j].r + c[j].m };

            double dx = c[j].x - c[i].x;
            double dy = c[j].y - c[i].y;
            double d2 = dx * dx + dy * dy;
            double d = sqrt(d2);

            if (d < EPS) continue; /* concentric or same center: no finite unique intersections */

            for (int ai = 0; ai < 2; ai++) {
                for (int aj = 0; aj < 2; aj++) {
                    double r1 = radii_i[ai];
                    double r2 = radii_j[aj];

                    if (d > r1 + r2 + EPS) continue;
                    if (d < fabs(r1 - r2) - EPS) continue;

                    double a = (r1 * r1 - r2 * r2 + d2) / (2.0 * d);
                    double h2 = r1 * r1 - a * a;
                    if (h2 < -EPS) continue;
                    if (h2 < 0) h2 = 0;
                    double h = sqrt(h2);

                    double xm = c[i].x + a * dx / d;
                    double ym = c[i].y + a * dy / d;

                    double rx = -dy * h / d;
                    double ry =  dx * h / d;

                    for (int s = 0; s < 2; s++) {
                        double px = xm + (s == 0 ? rx : -rx);
                        double py = ym + (s == 0 ? ry : -ry);

                        int cnt = 0;
                        for (int k = 0; k < n; k++) {
                            double ddx = px - c[k].x;
                            double ddy = py - c[k].y;
                            double dist = sqrt(ddx * ddx + ddy * ddy);
                            if (dist <= c[k].r + c[k].m + EPS && dist + EPS >= c[k].r) cnt++;
                        }
                        if (cnt > ans) ans = cnt;
                    }
                }
            }
        }
    }

    printf("%d\n", ans);
    free(c);
    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    static class Gem {
        double x, y, r, s;
        Gem(double x, double y, double r, double s) {
            this.x = x;
            this.y = y;
            this.r = r;
            this.s = s;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = br.readLine()) != null) {
            int N = Integer.parseInt(line.trim());
            if (N == 0) break;
            Gem[] gems = new Gem[N];
            for (int i = 0; i < N; i++) {
                String[] parts = br.readLine().trim().split("\\s+");
                double x = Double.parseDouble(parts[0]);
                double y = Double.parseDouble(parts[1]);
                double r = Double.parseDouble(parts[2]);
                double s = Double.parseDouble(parts[3]);
                gems[i] = new Gem(x, y, r, s);
            }

            int maxCount = 1; // at least one gem can be attracted
            // Try all pairs of gems to define candidate rod positions
            for (int i = 0; i < N; i++) {
                for (int j = i; j < N; j++) {
                    List<double[]> candidates = new ArrayList<>();
                    if (i == j) {
                        // For a single gem, we can place the rod at its center
                        candidates.add(new double[]{gems[i].x, gems[i].y});
                    } else {
                        // For two gems, find intersection of circles (center, effective radius)
                        double xi = gems[i].x, yi = gems[i].y, ri = gems[i].r + gems[i].s;
                        double xj = gems[j].x, yj = gems[j].y, rj = gems[j].r + gems[j].s;
                        double dx = xj - xi, dy = yj - yi;
                        double d = Math.sqrt(dx*dx + dy*dy);
                        if (d > ri + rj + 1e-12) continue;
                        if (d < Math.abs(ri - rj) - 1e-12) continue;
                        if (d < 1e-12) {
                            // concentric, add center
                            candidates.add(new double[]{xi, yi});
                        } else {
                            double a = (ri*ri - rj*rj + d*d) / (2*d);
                            double h = Math.sqrt(ri*ri - a*a);
                            double xm = xi + a * dx / d;
                            double ym = yi + a * dy / d;
                            candidates.add(new double[]{xm + h * dy / d, ym - h * dx / d});
                            candidates.add(new double[]{xm - h * dy / d, ym + h * dx / d});
                        }
                    }
                    for (double[] point : candidates) {
                        int count = 0;
                        for (Gem g : gems) {
                            double dist = Math.sqrt((point[0] - g.x)*(point[0] - g.x) + (point[1] - g.y)*(point[1] - g.y));
                            if (dist <= g.r + g.s + 1e-12) count++;
                        }
                        if (count > maxCount) maxCount = count;
                    }
                }
            }
            System.out.println(maxCount);
        }
    }
}

